-- setup.sql — sample database for: Exercise 1 — 1,000 rows, predicted pages, then proved with a DMV
-- Drops and re-creates the database DBI202_CL (a scratch database used only by Code Lab exercises), then the tables + rows.
-- Xoá và tạo lại CSDL DBI202_CL (CSDL nháp chỉ dùng cho bài Code Lab), rồi tạo bảng + dữ liệu. Chạy lại bất cứ lúc nào để làm sạch.
USE master;
GO
IF DB_ID(N'DBI202_CL') IS NOT NULL
BEGIN
    ALTER DATABASE DBI202_CL SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE DBI202_CL;
END
GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
-- Nothing to prepare: you create dbo.SanPham yourself in solution.sql.
SELECT 1 AS ready;
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: Exercise 1 — 1,000 rows, predicted pages, then proved with a DMV
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 4 checks ──────────';

-- CHECK 1: 1,000 rows, ma = 1…1000, gia = 1000 × ma
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF((SELECT COUNT(*) FROM dbo.SanPham) = 1000 AND (SELECT COUNT(DISTINCT ma) FROM dbo.SanPham) = 1000 AND (SELECT MIN(ma) FROM dbo.SanPham) = 1 AND (SELECT MAX(ma) FROM dbo.SanPham) = 1000 AND NOT EXISTS (SELECT 1 FROM dbo.SanPham WHERE gia <> 1000 * ma OR RTRIM(ten) <> CONCAT(''SP'', ma)), 1, 0);
SET @info = CONCAT(N''rows = '', (SELECT COUNT(*) FROM dbo.SanPham));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. 1,000 rows, ma = 1…1000, gia = 1000 × ma | 1.000 dòng, ma = 1…1000, gia = 1000 × ma'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. 1,000 rows, ma = 1…1000, gia = 1000 × ma | 1.000 dòng, ma = 1…1000, gia = 1000 × ma', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: The table is a heap with the three NOT NULL columns of the task
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N''dbo.SanPham'') AND index_id = 0) AND (SELECT COUNT(*) FROM sys.indexes WHERE object_id = OBJECT_ID(N''dbo.SanPham'')) = 1
  AND (SELECT COUNT(*) FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.SanPham'') AND c.is_nullable = 0 AND ((c.name = ''ma'' AND t.name = ''int'') OR (c.name = ''ten'' AND t.name = ''char'' AND c.max_length = 100) OR (c.name = ''gia'' AND t.name = ''int''))) = 3
  AND (SELECT COUNT(*) FROM sys.columns WHERE object_id = OBJECT_ID(N''dbo.SanPham'')) = 3, 1, 0);
SET @info = N''expected a heap (ma INT, ten CHAR(100), gia INT), all NOT NULL'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. The table is a heap with the three NOT NULL columns of the task | Bảng là heap với ba cột NOT NULL như đề'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. The table is a heap with the three NOT NULL columns of the task | Bảng là heap với ba cột NOT NULL như đề', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: vPageStats reports 115 bytes per row
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF((SELECT byte_moi_dong FROM dbo.vPageStats) = 115, 1, 0);
SET @info = CONCAT(N''byte_moi_dong = '', (SELECT TOP (1) byte_moi_dong FROM dbo.vPageStats), N'' (4 + 100 + 4 + 7)'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. vPageStats reports 115 bytes per row | vPageStats báo 115 byte mỗi dòng'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. vPageStats reports 115 bytes per row | vPageStats báo 115 byte mỗi dòng', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: vPageStats reports 15 pages = ceiling(1000 / 69)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF((SELECT so_trang FROM dbo.vPageStats) = 15, 1, 0);
SET @info = CONCAT(N''so_trang = '', (SELECT TOP (1) so_trang FROM dbo.vPageStats));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. vPageStats reports 15 pages = ceiling(1000 / 69) | vPageStats báo 15 trang = làm tròn lên 1000 / 69'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. vPageStats reports 15 pages = ceiling(1000 / 69) | vPageStats báo 15 trang = làm tròn lên 1000 / 69', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

